import re,json,sys
def load(u):
    t=open(f'{u}_act.html').read()
    s=[m.group(1) for m in re.finditer(r'<script[^>]*>(.*?)</script>',t,flags=re.S)][2]
    raw=re.search(r'boot\(\{[^}]*\},(".*")\);?\s*$',s,flags=re.S).group(1)
    arr=json.loads(json.loads(raw))
    memo={}
    def h(i):
        if i==-1: return None
        if i==-2: return None
        if i in memo: return memo[i]
        v=arr[i]
        if isinstance(v,list): r=[h(x) for x in v]
        elif isinstance(v,dict): r={k:h(x) for k,x in v.items()}
        else: r=v
        memo[i]=r; return r
    root=arr[0]
    return [h(i) for i in root]
d={u:load(u) for u in ['reset','webframp']}
json.dump(d,open('decoded.json','w'),indent=1)
for u,islands in d.items():
    print('=====',u)
    for isl in islands:
        if not isinstance(isl,dict): continue
        p=isl.get('props') or {}
        if 'snapshots' in p:
            for s in p['snapshots'][:20]: print(s['date'],s['totalScore'],s['totalEvents'],s['categoryTotals'])
            print('nsnap',len(p['snapshots']))
        if 'breakdown' in p:
            print('totalEvents',p['totalEvents'],'scoreSources',p['scoreSources'])
            for b in p['breakdown']:
                print(' source',b['name'],b['total'])
                for c in b['commands']:
                    subs=c['subcommands'] or []
                    print('  ',c['name'],c['total'],' '.join(f"{x['name']}={x['count']}" for x in subs))
        if 'initialEntries' in p:
            from collections import Counter
            E=p['initialEntries']
            print('entries',len(E),Counter((e['source'],e['category'],e['baseAmount'],e['multiplier']) for e in E).most_common(12))
EOF
python3 dec.py

